BEGIN;
CREATE TABLE app.supplier_document(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,supplier_context varchar(120) NOT NULL,document_type varchar(20) NOT NULL CHECK(document_type IN('invoice','credit','delivery')),document_number varchar(120),content_hash char(64) NOT NULL,status varchar(30) NOT NULL CHECK(status IN('ready','held')),hold_reason text,recognized_debt_pence bigint NOT NULL DEFAULT 0 CHECK(recognized_debt_pence=0),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id,id),UNIQUE(tenant_id,job_id,supplier_context,document_type,content_hash));
CREATE UNIQUE INDEX supplier_document_business_identity ON app.supplier_document(tenant_id,job_id,supplier_context,document_type,document_number) WHERE document_number IS NOT NULL AND status='ready';
CREATE TABLE app.supplier_document_version(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,document_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),media_type varchar(100) NOT NULL,byte_length integer NOT NULL CHECK(byte_length>0),content_hash char(64) NOT NULL,page_count integer NOT NULL CHECK(page_count>0),parent_version_id uuid,page_from integer,page_to integer,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,document_id,version),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_id)REFERENCES app.supplier_document(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,parent_version_id)REFERENCES app.supplier_document_version(tenant_id,job_id,id));
CREATE TABLE app.supplier_document_intake(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,document_id uuid,fixture_id varchar(80) NOT NULL,channel varchar(20) NOT NULL CHECK(channel IN('picker','fixture_mail')),alias varchar(200),result varchar(20) NOT NULL CHECK(result IN('ready','held','duplicate')),reason text,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_id)REFERENCES app.supplier_document(tenant_id,job_id,id));
CREATE TABLE app.goods_receipt(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,order_draft_id uuid NOT NULL,document_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),ordered_quantity numeric(20,6) NOT NULL CHECK(ordered_quantity>=0),delivered_quantity numeric(20,6) NOT NULL CHECK(delivered_quantity>=0),accepted_quantity numeric(20,6) NOT NULL CHECK(accepted_quantity>=0),rejected_quantity numeric(20,6) NOT NULL CHECK(rejected_quantity>=0),missing_quantity numeric(20,6) NOT NULL CHECK(missing_quantity>=0),unit varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,order_draft_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,order_draft_id)REFERENCES app.purchase_order_draft(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,document_id)REFERENCES app.supplier_document(tenant_id,job_id,id),CHECK(accepted_quantity+rejected_quantity<=delivered_quantity),CHECK(missing_quantity=ordered_quantity-accepted_quantity));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['supplier_document','supplier_document_version','supplier_document_intake','goods_receipt'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
COMMIT;
